import { createState, collides, frame } from '../game/neon.js';

// Mock canvas context
const ctx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
  fillStyle: '',
};

test('D1 — Brick collision does not deflect ball', () => {
  const state = createState(1);
  // Position ball so it's about to hit a brick from below
  // Brick 0 is at (offsetX, BRICK_TOP)
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h + 2; // Just below the brick
  state.ball.vy = -100; // Moving UP

  // One step to ensure collision
  // Instead of calling step(), let's just force the collision in frame()
  // as that's where the bug is.
  state.ball.y -= 10; // Now it's definitely overlapping

  assert.strictEqual(collides(state.ball, brick), true, 'Ball should collide with brick');

  const initialVy = state.ball.vy;
  frame(ctx, state);

  assert.notStrictEqual(state.ball.vy, initialVy, 'Ball vy should have changed after brick collision');
});

